/* The primary's SCPI command tree of z3805a-3543b.bin as C data: its tree pair,
 * the common commands' list and the main tree, and every record they reach,
 * each of the type tools/ghidra/types/smartclock.h declares and reproducing the
 * image's bytes but for its pointers. Generated by `make scpi-tree`
 * (smartclock-cli dump-scpi --c --names-file z3805a-3543b.tsv z3805a-3543b.bin,
 * then clang-format); do not edit by hand.  docs/scpi/README.md, "As C", gives
 * the names; a field left out is zero.  A record's pointer is cast to its
 * field's type, since the records are const and the fields are not: Ghidra's
 * types, which the exported C compiles this with, keep no const.  A
 * converter's and a formatter's are cast too, their prototypes not
 * the field's own; a handler's is not.  A child list's children
 * are an array of their own, which follows the list as in the
 * image.  Defining SCPI_TREE_DATA_ALONE declares the routines, to compile the
 * file alone. */

#include <stddef.h>

